using System; using System.Threading.Tasks; using Microsoft.SemanticKernel; using Microsoft.SemanticKernel.Connectors.DeepSeek; using Microsoft.SemanticKernel.ChatCompletion; namespace SemanticKernelDemo.DeepSeek; /// <summary> /// DeepSeek demo showing reasoning content support. /// </summary> public class DeepSeekDemo { public static async Task RunAsync() { Console.WriteLine("======== DeepSeek Demo ========"); // Replace with your actual DeepSeek API key and model ID string apiKey = "your-api-key-here"; string modelId = "deepseek-v4-pro"; // Create kernel with DeepSeek chat completion service var kernel = Kernel.CreateBuilder() .AddDeepSeekChatCompletion( modelId: modelId, apiKey: apiKey) .Build(); // Create execution settings with high reasoning effort. var executionSettings = new DeepSeekPromptExecutionSettings { MaxTokens = 2000, ReasoningEffort = "high" }; // Create KernelArguments using the execution settings. var kernelArgs = new KernelArguments(executionSettings); // Create chat history var chatHistory = new ChatHistory(); chatHistory.AddUserMessage("9.11 和 9.8，哪个更大？"); // Get response from the model var response = await kernel.GetChatMessageContentAsync(chatHistory, kernelArgs); // Check if the response is a DeepSeekChatMessageContent if (response is DeepSeekChatMessageContent deepSeekResponse) { // Print the reasoning content if available if (!string.IsNullOrEmpty(deepSeekResponse.ReasoningContent)) { Console.WriteLine("Reasoning Content:"); Console.WriteLine(deepSeekResponse.ReasoningContent); Console.WriteLine(); } // Print the final answer Console.WriteLine("Final Answer:"); Console.WriteLine(deepSeekResponse.Content); } else { Console.WriteLine("Response is not a DeepSeekChatMessageContent"); } // Continue the conversation with another question chatHistory.AddAssistantMessage(response.Content ?? string.Empty); // Also add the reasoning content to the chat history if available if (response is DeepSeekChatMessageContent deepSeekResponseWithReasoning) { if (!string.IsNullOrEmpty(deepSeekResponseWithReasoning.ReasoningContent)) { // Store reasoning content in metadata var metadata = new System.Collections.Generic.Dictionary<string, object?> { { "ReasoningContent", deepSeekResponseWithReasoning.ReasoningContent } }; chatHistory.AddAssistantMessage(deepSeekResponseWithReasoning.Content ?? string.Empty, metadata); } } chatHistory.AddUserMessage("草莓这个单词中有多少个R？"); // Get response to the second question var response2 = await kernel.GetChatMessageContentAsync(chatHistory, kernelArgs); // Check if the response is a DeepSeekChatMessageContent if (response2 is DeepSeekChatMessageContent deepSeekResponse2) { // Print the reasoning content if available if (!string.IsNullOrEmpty(deepSeekResponse2.ReasoningContent)) { Console.WriteLine("\nReasoning Content:"); Console.WriteLine(deepSeekResponse2.ReasoningContent); Console.WriteLine(); } // Print the final answer Console.WriteLine("Final Answer:"); Console.WriteLine(deepSeekResponse2.Content); } else { Console.WriteLine("Response is not a DeepSeekChatMessageContent"); } } } 